import {hasSandboxWorld,sandboxFinance,sandboxMarket,sandboxProfile,worldPlayer,sandboxLabel,legalClub} from './sandbox-world.js';
import {managerReport,managerAvailable} from './manager-career.js';
import {recruitmentAllowance} from './career-market.js';
import {pounds} from './manager-money.js';
import {escapeHtml as esc} from './ui-kit.js';
export function sandboxFinancePanel(c){
 if(!hasSandboxWorld(c))return '';const f=sandboxFinance(c),allowance=recruitmentAllowance(c);
 return `<section class="card mode-card sandbox-finance"><span class="eyebrow">TWELVE-MONTH PLANNING</span><h3>Keep recruitment and wages in balance.</h3><div class="studio-metrics">${[...(c.careerRulesVersion===2&&c.setup.custom?[['Founding capital',c.setup.startingBudget*500000],['Completed recruitment fees',c.management.ledger.filter(l=>['buy','loan','delegated-buy'].includes(l.kind)).reduce((n,l)=>n-l.amount*500000,0)]]:[]),['Cash after reserved fees',f.cash-f.reserved],['Current weekly wages',f.weekly],['Reserved transfer fees',f.reserved],['Annual committed wages',f.annualWages],['Forecast closing cash',f.forecast]].map(([label,n])=>`<div class="studio-metric"><span>${label}</span><strong>${pounds(n)}</strong></div>`).join('')}</div><p class="stat-foot">Authored annual receipts ${pounds(f.annualReceipts)}; ${c.careerRulesVersion===2?'accrued by elapsed days; weekly wages accrue per seven days.':'paid in 38 instalments. Wages cover 52 weeks.'} Forecast assumes the current squad and excludes future deals, renewals and sale proceeds. There is no automatic season cash grant.</p><p>Delegated recruitment: ${allowance?allowance.enabled?allowance.open?`${pounds(allowance.feesRemaining)} transfer allowance and ${pounds(allowance.weeklyRemaining)}/week added wage allowance remaining for ${esc(allowance.window)}.`:'Window closed; limits apply when recruitment reopens.':'manual control.':'unavailable in this save.'} Allowances limit purchases; they do not add cash to the club.</p><p>Recruitment priority: ${esc(c.management.recruitmentPriority)}</p>${f.forecast<0?'<p class="manager-contract-alert">Your current wage commitments exceed projected resources. Reduce costs before spending further.</p>':''}</section>`;
}
export function foundingBuilder(c){
 if(!hasSandboxWorld(c)||!c.setup.custom||c.competition.round>0)return '';const originals=c.xi.concat(c.bench).filter(id=>id.startsWith('founder-'));if(!originals.length)return '';
 const role=c.management.foundingRole||'FWD',outgoing=originals.filter(id=>sandboxProfile(id).role===role),pool=sandboxMarket(c).filter(p=>p.role===role&&!p.onLoan).sort((a,b)=>b.rating-a.rating||a.name.localeCompare(b.name)).filter(p=>legalClub(c,p.worldRegistration,worldPlayer(c,p.id).id)).slice(0,32),target=pool.find(p=>p.id===c.management.foundingTarget)||pool[0],report=target?managerReport(c,target.id):null,outgoingId=outgoing.includes(c.management.foundingOutgoing)?c.management.foundingOutgoing:outgoing[0],settlement=outgoingId?c.condition[outgoingId].wage*4:0;
 return `<section class="card mode-card founding-builder"><span class="eyebrow">PRE-SEASON SQUAD BUILDER</span><h3>Recruit before your first kickoff.</h3><p>Available funds <strong>${pounds(managerAvailable(c)*500000)}</strong>.</p><p>Replace an original starter player with a signing in the same position. Review the selected player's fee and wage, then confirm the swap. The released player becomes unattached; no sale income is invented.</p><nav class="mode-tabs" aria-label="Founding recruitment positions">${['GK','DEF','MID','FWD'].map(r=>`<button class="btn ${r===role?'primary':'secondary'}" data-action="eu-mg-founding-role" data-choice="${r}" aria-pressed="${r===role}">${r}</button>`).join('')}</nav>${outgoing.length&&target?`<form data-manager-form="founder-sign"><label>Original player to replace<select name="outgoing" data-founder-outgoing>${outgoing.map(id=>`<option value="${id}" ${id===outgoingId?'selected':''}>${esc(sandboxProfile(id).name)} · ${c.xi.includes(id)?'Starter':'Reserve'}</option>`).join('')}</select></label><label>Incoming player<select name="incoming" data-founder-target>${pool.map(p=>`<option value="${p.id}" ${target.id===p.id?'selected':''}>${esc(p.name)} · ${p.rating} OVR</option>`).join('')}</select></label><p><strong>${esc(target.name)}</strong> · ${esc(target.club)}</p><p>Fee ${pounds(report.fee*500000)} · wage ${pounds(report.wage*500000)}/week · contract through June ${2025+c.season+2}. Release settlement ${pounds(settlement*500000)} (four weeks of the outgoing player's wage). Cash after fee and settlement: ${pounds((c.credits-report.fee-settlement)*500000)}.</p><button class="btn primary" type="submit">Sign & replace original player</button></form>`:'<p>No original players remain in this position. Use Transfers for further changes.</p>'}</section>`;
}
export function sandboxFixtureContext(c,opponent){
 if(!hasSandboxWorld(c)||!opponent)return '';const me=c.world.clubs.find(t=>t.id==='user'),them=c.world.clubs.find(t=>t.id===opponent.id),recent=c.history.filter(h=>h.opponent===opponent.name).at(-1),manchester=[me.name,them.name].every(n=>n.startsWith('Manchester ')),clasico=[me.name,them.name].sort().join('|')==='Barcelona|Real Madrid';
 return `<p class="fixture-context">${manchester?'Manchester derby':clasico?'El Clásico':me.country===them.country?me.country+' meeting':me.country+' × '+them.country} · ${sandboxLabel(c)}${recent?' · last meeting '+recent.score.join('–'):''}</p><p class="stat-foot">Generic ${them.stadium} stadium profile · ${them.lighting} presentation. Club kit colours and patterns carry through to live matches.</p>`;
}

